import 'dart:convert';
import 'dart:io';

/// Folder holding the oracle fixtures generated by `tools/lunar_oracle/`.
///
/// `dart test` runs with the package root as the working directory, so the
/// path is relative to `packages/lunar_calendar/`.
const String fixturesDir = 'test/fixtures';

/// Reads and decodes one JSON fixture file as a map.
Map<String, Object?> loadFixture(String fileName) {
  final file = File('$fixturesDir/$fileName');
  final decoded = jsonDecode(file.readAsStringSync());
  if (decoded is! Map<String, Object?>) {
    throw FormatException('Fixture $fileName is not a JSON object');
  }
  return decoded;
}
